BEGIN; INSERT INTO clinics(id,name,clerk_org_id) VALUES('ci-e18-a','CI E18 A','ci_e18_org_a'),('ci-e18-b','CI E18 B','ci_e18_org_b') ON CONFLICT(id) DO NOTHING; INSERT INTO workforce_runs(id,clinic_id,workforce_key,idempotency_key) VALUES('ci-e18-run-a','ci-e18-a','patient-journey','ci-e18-key') ON CONFLICT(id) DO NOTHING; SET ROLE authenticated; SELECT set_config('app.clerk_org_id','ci_e18_org_a',false); DO 'BEGIN IF NOT EXISTS(SELECT 1 FROM workforce_runs WHERE id=''ci-e18-run-a'') THEN RAISE EXCEPTION ''tenant A cannot read workforce run''; END IF; END'; SELECT set_config('app.clerk_org_id','ci-e18_org_b',false); DO 'BEGIN IF EXISTS(SELECT 1 FROM workforce_runs WHERE id=''ci-e18-run-a'') THEN RAISE EXCEPTION ''cross-tenant workforce read''; END IF; END'; RESET ROLE; ROLLBACK;